        # Small penalty if moving away from advantage against opponent target by keeping distance to opponent increasing.
        damp = cheb(nx, ny, tx, ty) - cheb(ox, oy, tx, ty)
        score = (dcur, damp, abs(nx - tx) + abs(ny - ty))
